#!/usr/bin/env node

/**
 * Reading a client extension's OAuth2 credentials out of the routes tree.
 *
 * Liferay exposes no API for creating an OAuth2 application - there is no
 * dynamic registration endpoint, `POST /o/oauth2/application` answers 405, and
 * no headless admin API covers it. An application that must exist in every
 * freshly built instance therefore has to be declared as a client extension,
 * and its credentials are generated by Liferay rather than chosen by us.
 *
 * Liferay publishes them through the routes tree, which LDM mounts into every
 * container and which is readable on the host as well. This reads one
 * application's pair out of it, so a caller outside the workload - the CLI, or
 * a script setting up a run - can authenticate as that application (#988).
 *
 * Prints shell assignments by default, or JSON with --json. Exits non-zero and
 * explains when the application is not present, because the alternative is a
 * run that proceeds with an empty credential and fails much later as a 403
 * that looks like a policy decision.
 */

const { lxcConfig } = require('@rotty3000/config-node');

const USAGE = `Usage: read-oauth-credentials.cjs <external-reference-code> [--json] [--prefix NAME]

  --json          emit JSON rather than shell assignments
  --prefix NAME   variable prefix for shell output (default AICA_ADMIN_CLIENT)

Requires the routes tree to be visible, which LDM arranges through
LIFERAY_ROUTES_CLIENT_EXTENSION / LIFERAY_ROUTES_DXP.`;

function parseArgs(argv) {
  const options = { json: false, prefix: 'AICA_ADMIN_CLIENT' };
  const positional = [];

  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];

    if (arg === '--json') {
      options.json = true;
    } else if (arg === '--prefix') {
      options.prefix = argv[i + 1];
      i += 1;
    } else if (arg.startsWith('--prefix=')) {
      options.prefix = arg.slice('--prefix='.length);
    } else if (arg === '-h' || arg === '--help') {
      options.help = true;
    } else {
      positional.push(arg);
    }
  }

  options.erc = positional[0];

  return options;
}

/**
 * The application's credentials, or a reason there are none.
 *
 * `lxcConfig.oauthApplication` returns undefined for an external reference code
 * the routes tree does not list, which is the same shape as a tree that is not
 * mounted at all. The two are worth telling apart: one is a client extension
 * that failed to deploy, the other an environment that was never wired up.
 */
function readCredentials(erc) {
  let application;

  try {
    application = lxcConfig.oauthApplication(erc);
  } catch (_error) {
    // The library reads the list of external reference codes and calls
    // `.includes` on it without checking, so an absent routes tree arrives here
    // as a TypeError rather than an empty result. That distinction is worth
    // keeping: this is an environment that was never wired up, not a client
    // extension that failed to deploy.
    return {
      error:
        `The routes tree is not readable, so no OAuth2 application can be ` +
        `resolved.\n` +
        `   LIFERAY_ROUTES_CLIENT_EXTENSION and LIFERAY_ROUTES_DXP must point ` +
        `at it.\n` +
        `   LDM mounts it into every container and it is readable on the host ` +
        `too.`,
    };
  }

  if (!application) {
    return {
      error:
        `No OAuth2 application '${erc}' in the routes tree.\n` +
        `   The routes tree is readable but does not list that external ` +
        `reference code,\n` +
        `   so the client extension declaring it was not deployed.`,
    };
  }

  const clientId = application.clientId();
  const clientSecret = application.clientSecret();

  // A headless-server application is the only kind with a secret to read. A
  // user-agent one resolves a client id and nothing else, and returning that
  // pair half-filled would be sent as an exchange that fails at Liferay.
  if (!clientId || !clientSecret) {
    return {
      error:
        `OAuth2 application '${erc}' has no client credentials.\n` +
        `   A headless-server application is required; a user-agent one has no\n` +
        `   secret to read.`,
    };
  }

  return { clientId, clientSecret, tokenUri: application.tokenUri() };
}

function main() {
  const options = parseArgs(process.argv.slice(2));

  if (options.help || !options.erc) {
    console.error(USAGE);
    process.exit(options.help ? 0 : 2);
  }

  const result = readCredentials(options.erc);

  if (result.error) {
    console.error(`❌ ${result.error}`);
    process.exit(1);
  }

  if (options.json) {
    console.log(JSON.stringify(result, null, 2));
    return;
  }

  // Single-quoted with any embedded quote escaped, so a secret containing shell
  // metacharacters is still assigned verbatim by `eval`.
  const quote = (value) => `'${String(value).replace(/'/g, `'\\''`)}'`;

  console.log(`${options.prefix}_ID=${quote(result.clientId)}`);
  console.log(`${options.prefix}_SECRET=${quote(result.clientSecret)}`);
}

if (require.main === module) {
  main();
}

module.exports = { parseArgs, readCredentials };
